﻿"use client";

import Image from "next/image";\nimport React, { useEffect, useState } from "react";
import Link from "next/link";
import { Bell, Search, Star } from "lucide-react";
import CreateAlertModal from "./CreateAlertModal";
import WatchlistButton from "@/components/WatchlistButton";
import ChangePill from "@/components/ChangePill";
import PriceFlash from "@/components/PriceFlash";
import { useLiveQuotes } from "@/hooks/useLiveQuotes";
import { SearchButton } from "@/components/SearchCommand";
import { formatNumber, formatPrice } from "@/lib/utils";
import { hasFinnhubQuotes } from "@/lib/markets";
import type { getWatchlistData } from "@/lib/actions/finnhub.actions";

type Row = Awaited<ReturnType<typeof getWatchlistData>>[number];
const SUGGESTIONS = ['AAPL', 'NVDA', 'MSFT', 'TSLA', 'AMZN'];

export default function WatchlistTable({ initialRows }: { initialRows: Row[] }) {
    const [baseRows, setBaseRows] = useState(initialRows);
    const live = useLiveQuotes(baseRows.map((r) => r.symbol));

    // Server re-renders (after add/remove) replace the local copy
    useEffect(() => setBaseRows(initialRows), [initialRows]);

    const rows = baseRows.map((r) => {
        const q = live[r.symbol];
        return q?.c ? { ...r, price: q.c, change: q.d ?? r.change, changePercent: q.dp ?? r.changePercent } : r;
    });

    if (rows.length === 0) {
        return (
            <div className="empty-state">
                <span className="empty-icon"><Star className="size-5" /></span>
                <h3>Henüz izleme listenizde hisse yok</h3>
                <p className="max-w-sm">Bir şirket arayın, fiyatını burada takip etmek ve uyarı ayarlamak için yıldızlayın.</p>
                <SearchButton className="btn btn-primary mt-3"><Search /> Hisseleri ara</SearchButton>
                <div className="mt-4 flex flex-wrap justify-center gap-1.5">
                    {SUGGESTIONS.map((s) => (
                        <Link key={s} href={`/stocks/${s}`} className="pill mono h-7 px-3 hover:bg-hover hover:text-foreground">{s}</Link>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="overflow-x-auto rounded-[14px]">
            <table className="data-table">
                <thead>
                    <tr>
                        <th>Şirket</th>
                        <th className="is-num">Fiyat</th>
                        <th className="is-num">Bugün</th>
                        <th className="is-num">Değişim</th>
                        <th className="is-num">Piyasa değeri</th>
                        <th className="w-[88px]"><span className="sr-only">İşlemler</span></th>
                    </tr>
                </thead>
                <tbody>
                    {rows.map((row) => (
                        <tr key={row.symbol}>
                            <td className="max-w-[320px]">
                                <Link href={`/stocks/${row.symbol}`} className="group flex items-center gap-3">
                                    {row.logo ? (
                                        <span className="logo-well"><Image src={row.logo} alt="" className="size-full object-contain p-1" /></span>
                                    ) : (
                                        <span className="logo-well is-empty">{row.symbol[0]}</span>
                                    )}
                                    <span className="min-w-0">
                                        <span className="block truncate font-semibold text-foreground group-hover:text-brand-ink transition-colors" title={row.name}>{row.name}</span>
                                        <span className="mono block text-[12px] text-faint">{row.symbol}</span>
                                    </span>
                                </Link>
                            </td>
                            <td className="is-num font-semibold text-foreground">
                                <PriceFlash value={row.price} className="px-1">{row.price ? formatPrice(row.price, row.currency) : '—'}</PriceFlash>
                            </td>
                            <td className="is-num"><ChangePill value={row.price ? row.changePercent : null} /></td>
                            <td className="is-num text-muted-foreground">{row.price ? `${row.change > 0 ? '+' : ''}${row.change.toFixed(2)}` : '—'}</td>
                            <td className="is-num text-muted-foreground">{row.marketCap ? formatNumber(row.marketCap) : '—'}</td>
                            <td>
                                <div className="flex items-center justify-end gap-1">
                                    {hasFinnhubQuotes(row.symbol) ? (
                                        <CreateAlertModal symbol={row.symbol} currentPrice={row.price} currency={row.currency}>
                                            <button type="button" className="icon-btn" title={`İçin fiyat uyarısı ayarla ${row.symbol}`} aria-label={`İçin fiyat uyarısı ayarla ${row.symbol}`}>
                                                <Bell />
                                            </button>
                                        </CreateAlertModal>
                                    ) : (
                                        <span className="icon-btn opacity-40" title="Uyarılar ABD hisseleri ve kripto için mevcuttur"><Bell /></span>
                                    )}
                                    <WatchlistButton
                                        symbol={row.symbol}
                                        company={row.name}
                                        isInWatchlist
                                        variant="icon"
                                        onWatchlistChange={(sym, added) => {
                                            if (!added) setBaseRows((current) => current.filter((r) => r.symbol !== sym));
                                        }}
                                    />
                                </div>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

﻿/**
 * OpenStock Bot Scheduler - Inngest
 * Belirli aralıklarla tüm çalışan botları tetikler
 */

import { inngest } from '@/lib/inngest/client';
import { Bot } from '@/database/models/Bot';
import { connectToDatabase } from '@/database/mongoose';
import { runBotCycle } from '@/lib/bot/paper-trading';
import { logError, logInfo } from '@/lib/logger';

// Her 15 dakikada bir tüm working botları çalıştır
export const runAllBots = inngest.createFunction(
    { id: 'run-all-bots', name: 'Run All Trading Bots', triggers: [{ cron: '*/15 * * * *' }] },
    async ({ event, step }: { __event: unknown; step: unknown }) => {
        await connectToDatabase();

        const bots = await Bot.find({ status: 'running', isPaper: true }).lean();

        logInfo(`Bot scheduler: ${bots.length} working bot bulundu`);

        for (const bot of bots) {
            try {
                await step.run(`run-bot-${bot._id}`, async () => {
                    const result = await runBotCycle(bot._id.toString());
                    if (result.error) {
                        logError(`Bot "${bot.name}" çalıştırma hatası`, new Error(result.error));
                    } else {
                        logInfo(`Bot "${bot.name}" çalıştırıldı: ${result.signals.length} sinyal, ${result.trades.length} işlem`);
                    }
                });
            } catch (err) {
                logError(`Bot "${bot.name}" scheduler hatası`, err);
            }
        }

        return { processed: bots.length };
    }
);

// Tek bot'u manuel çalıştırma (API'den çağrılır)
export const runSingleBot = inngest.createFunction(
    { id: 'run-single-bot', name: 'Run Single Trading Bot', triggers: [{ event: 'app/bot.run' }] },
    async ({ event, step }: { __event: unknown; step: unknown }) => {
        await connectToDatabase();

        const { botId } = event.data;

        try {
            const result = await step.run(`run-bot-${botId}`, async () => {
                return await runBotCycle(botId);
            });

            return result;
        } catch (err) {
            logError(`Bot "${botId}" çalıştırma hatası`, err);
            throw err;
        }
    }
);
